import codecs
original = codecs.lookup_error('strict')
name = 'utf\ud800'
seen = []
def repair(error):
    seen.append(error.object is name)
    return (b'8', error.end)
codecs.register_error('strict', repair)
for attempt in range(2):
    try:
        print(repr('x'.encode(name)))
    except Exception as error:
        print(type(error).__name__, ascii(str(error)))
    codecs.register_error('strict', original)
print(seen)

